<template>
 <NotificationDialog :model-value="modelValue" :title="title" :subtitle="subtitle" :badge="row?.platform_label" width="min(960px,96vw)" align-center :close-on-click-modal="false" :show-close="!locked" :close-on-press-escape="!locked" @update:model-value="close">
  <div v-if="row" class="payment-confirmation">
   <aside class="payment-overview" aria-label="申请单信息">
    <div class="payment-amount"><span>申请金额</span><strong>{{row.amount_cents===null?'金额待核':yuan(row.amount_cents)}}</strong><el-tag :type="row.needs_review?'danger':row.completed_at?'success':'warning'">{{row.state_label}}</el-tag></div>
    <dl class="payment-fields"><div><dt>申请人</dt><dd>{{row.applicant_name||'待匹配姓名'}}</dd></div><div><dt>发起门店</dt><dd>{{row.store_match?.store_name||'待绑定'}}</dd></div><div><dt>原申请部门</dt><dd>{{row.department||'—'}}</dd></div><div><dt>审批单号</dt><dd class="payment-number">{{row.business_no||'—'}}</dd></div><div><dt>申请时间</dt><dd>{{sourceTime(row.source_created_at)}}</dd></div><div v-if="row.completed_at"><dt>上次确认</dt><dd>{{localTime(row.completed_at)}}</dd></div></dl>
    <div class="payment-reason"><span>申请事由</span><p>{{row.reason||row.title||'—'}}</p></div>
   </aside>
   <section class="payment-workarea" :aria-label="action==='complete'?'付款确认表单':'付款记录详情'">
    <p v-if="row.needs_review" class="payment-review">原审批信息已变更。请重新核对金额及付款情况，上传当前凭证；历史记录继续保留。</p>
    <template v-if="action==='reopen'"><h3>更正完成标记</h3><p class="payment-helper">仅更正清单状态，不退回银行款项。原经办记录和付款凭证继续保留。</p><el-form label-position="top"><el-form-item label="更正原因" required><el-input v-model="note" :disabled="locked" type="textarea" :rows="4" maxlength="300" show-word-limit placeholder="说明本次更正的原因"/></el-form-item></el-form></template>
    <template v-else>
     <div class="payment-section-title"><h3>付款凭证 <span v-if="action==='complete'" class="payment-required">必传</span></h3><span v-if="action==='complete'">已选 {{proofIds.length}} / 5</span></div>
     <el-upload v-if="action==='complete'" ref="uploadRef" class="payment-dropzone" drag multiple :auto-upload="false" :show-file-list="false" accept=".jpg,.jpeg,.png,.webp,.pdf" :disabled="locked||proofLoading||loadFailed" :on-change="chooseFile" @paste="pasteFiles">
      <el-icon class="payment-upload-icon"><UploadFilled/></el-icon><div class="payment-upload-title">拖拽文件到此处，或<span>点击上传</span></div><p>支持图片、PDF，单份 ≤8MB，最多5份；也可粘贴截图</p>
     </el-upload>
     <div v-if="proofLoading" class="payment-empty" role="status">正在读取付款凭证…</div>
     <div v-else-if="!currentFiles.length" class="payment-empty">{{action==='complete'?'上传付款截图或银行回单，成功后将显示在这里':'暂无付款凭证'}}</div>
     <ul v-else class="payment-file-list" aria-label="本次付款凭证">
      <li v-for="file in currentFiles" :key="file.clientId||file.id" class="payment-file" :class="{'is-failed':file.uploadState==='failed'}">
       <button class="payment-file-thumb" type="button" :disabled="locked&&!file.thumb||file.uploadState==='failed'" :aria-label="(file.mime?.startsWith('image/')?'预览凭证 ':'下载凭证 ')+file.name" @click="view(file)"><img v-if="file.thumb&&file.mime?.startsWith('image/')" :src="file.thumb" alt="付款凭证缩略图"/><el-icon v-else><Picture v-if="file.mime?.startsWith('image/')"/><Document v-else/></el-icon><span v-if="!file.thumb||file.mime==='application/pdf'">{{file.mime==='application/pdf'?'PDF':'预览'}}</span></button>
       <div class="payment-file-info"><strong :title="file.name">{{file.name}}</strong><div class="payment-file-meta"><span>{{size(file.bytes)}}</span><span :class="file.uploadState==='failed'?'payment-file-error':''">{{fileStatus(file)}}</span></div><el-progress v-if="file.uploadState==='uploading'" :percentage="file.progress" :stroke-width="4" :show-text="false"/><p v-if="file.error" class="payment-file-error">{{file.error}}</p></div>
       <div class="payment-file-actions"><el-checkbox v-if="action==='complete'&&file.can_select" v-model="proofIds" :value="file.id" :disabled="locked" :aria-label="'选用凭证 '+file.name">选用</el-checkbox><el-button v-if="file.uploadState==='failed'" link type="primary" :disabled="locked" @click="retry(file)">重试</el-button><el-button v-if="action==='complete'&&(!file.id||file.can_remove)" link :disabled="locked" @click="remove(file)">移除</el-button><el-button v-if="file.id&&action!=='complete'" link :disabled="locked" @click="download(file)">下载</el-button></div>
      </li>
     </ul>
     <details v-if="historyFiles.length" class="payment-history"><summary>历史凭证（{{historyFiles.length}}份）</summary><p>历史原件保留，不计入本次付款确认。</p><ul><li v-for="file in historyFiles" :key="file.id"><span>{{file.name}} <small>{{file.confirmed_at?'已留档':'历史上传'}}</small></span><el-button link :disabled="locked" @click="view(file)">{{file.mime?.startsWith('image/')?'预览':'下载'}}</el-button><el-button v-if="action==='complete'&&file.can_remove" link :disabled="locked" @click="remove(file)">移除</el-button></li></ul></details>
     <template v-if="action==='complete'"><el-form class="payment-note" label-position="top"><el-form-item label="付款说明" required><el-input v-model="note" :disabled="locked" type="textarea" :rows="2" maxlength="300" show-word-limit placeholder="填写付款核实情况，便于后续追溯"/></el-form-item></el-form><el-checkbox v-model="confirmed" :disabled="locked" class="payment-confirm-check">已核实款项全部付清，所选凭证与本单一致</el-checkbox></template>
     <div v-else-if="row.completed_note" class="payment-read-note"><h3>付款说明</h3><p>{{row.completed_note}}</p></div>
    </template>
    <p v-if="feedback" class="payment-feedback" role="status">{{feedback}}</p><p v-if="error" class="ledger-error" role="alert">{{error}} <el-button v-if="loadFailed" link @click="loadFiles">重新读取</el-button></p>
   </section>
  </div>
  <template #footer><span class="payment-footer-hint" role="status">{{action==='details'?'凭证仅供授权财务和管理员查看':submitHint||'信息已齐全，可确认本单款项'}}</span><el-button v-if="action==='details'&&row?.completed_at" link :disabled="locked" @click="action='reopen';note='';error=''">更正完成标记</el-button><el-button :disabled="locked" @click="close(false)">{{action==='details'?'关闭':'取消'}}</el-button><el-button v-if="action!=='details'" type="primary" :disabled="!!submitHint" :loading="submitting" @click="submit">{{action==='reopen'?'确认更正':'确认款项'}}</el-button></template>
 </NotificationDialog>
 <el-image-viewer v-if="previewUrl" :url-list="[previewUrl]" teleported @close="previewUrl=''"/>
</template>
<script setup>
import {computed,inject,onBeforeUnmount,ref,watch} from 'vue'
import {Document,Picture,UploadFilled} from '@element-plus/icons-vue'
import {businessLedgerApi} from '@/api'
import NotificationDialog from './NotificationDialog.vue'
import '@/styles/business-ledger.css'
const props=defineProps({modelValue:Boolean,row:Object,mode:{type:String,default:'complete'}}),emit=defineEmits(['update:modelValue','saved'])
const api=inject('approvalPaymentApi',businessLedgerApi)
const action=ref('complete'),files=ref([]),proofIds=ref([]),note=ref(''),confirmed=ref(false),proofLoading=ref(false),uploading=ref(false),submitting=ref(false),working=ref(false),loadFailed=ref(false),error=ref(''),feedback=ref(''),previewUrl=ref(''),uploadRef=ref(null)
const locked=computed(()=>uploading.value||submitting.value||working.value),currentFiles=computed(()=>files.value.filter(f=>!f.confirmed_at&&(f.current||!f.id))),historyFiles=computed(()=>files.value.filter(f=>f.id&&(f.confirmed_at||!f.current)))
const title=computed(()=>({complete:'确认款项',details:'款项详情',reopen:'更正完成标记'})[action.value]),subtitle=computed(()=>action.value==='complete'?'核对申请信息，上传付款凭证后确认本单已付清。':'查看申请信息和付款留档记录。')
const submitHint=computed(()=>locked.value?'正在处理，请稍候':action.value==='reopen'?!note.value.trim()?'请填写更正原因':'':proofLoading.value||loadFailed.value?'请先读取付款凭证':files.value.some(f=>['queued','uploading','failed'].includes(f.uploadState))?'请完成上传，或移除失败的文件':!proofIds.value.length?'请至少上传并选用1份付款凭证':!note.value.trim()?'请填写付款说明':!confirmed.value?'请核实付清并勾选确认':'')
const yuan=v=>'￥'+(v/100).toFixed(2),sourceTime=v=>v?String(v).replace('T',' ').replace(/Z$/,''):'—',localTime=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—',size=v=>v>=1048576?(v/1048576).toFixed(1)+'MB':Math.max(1,Math.ceil(v/1024))+'KB'
const fileStatus=f=>f.uploadState==='uploading'?`上传中 ${f.progress}%`:f.uploadState==='queued'?'等待上传':f.uploadState==='failed'?'上传失败':f.confirmed_at?'已留档':f.can_select?'上传成功':f.current?'其他经办人上传':'历史上传'
let session=0
function clear(){for(const f of files.value)if(f.thumb)URL.revokeObjectURL(f.thumb);files.value=[];proofIds.value=[];previewUrl.value=''}
function close(value){if(!value&&!locked.value)emit('update:modelValue',false)}
watch(()=>[props.modelValue,props.row?.id,props.mode],()=>{session++;clear();note.value='';confirmed.value=false;error.value='';feedback.value='';action.value=props.mode;loadFailed.value=false;proofLoading.value=false;if(props.modelValue&&props.row)loadFiles()},{immediate:true})
async function loadFiles(){const n=session,row=props.row;if(!row)return;proofLoading.value=true;loadFailed.value=false;error.value='';try{const r=await api.approvalProofs(row.id);if(n!==session)return;clear();files.value=r.items.map(p=>({...p,uploadState:'uploaded',thumb:''}));proofIds.value=r.items.filter(p=>p.can_select).map(p=>p.id)}catch(e){if(n===session){loadFailed.value=true;error.value=e.message}}finally{if(n===session)proofLoading.value=false}}
function chooseFile(upload){if(upload.raw)addFiles([upload.raw]);queueMicrotask(()=>uploadRef.value?.clearFiles())}
function pasteFiles(event){const pasted=Array.from(event.clipboardData?.files||[]);if(pasted.length){event.preventDefault();addFiles(pasted)}}
function addFiles(incoming){
 if(locked.value||proofLoading.value||loadFailed.value||action.value!=='complete')return;feedback.value='';error.value=''
 for(const file of incoming){
  if(!/\.(jpe?g|png|webp|pdf)$/i.test(file.name)||!file.size||file.size>8*1024*1024){feedback.value='已跳过不支持、空白或超过8MB的文件：'+file.name;continue}
  if(files.value.some(f=>!f.confirmed_at&&f.name===file.name&&f.bytes===file.size)){feedback.value='文件已在列表中；失败项可单独重试。';continue}
  if(files.value.filter(f=>!f.confirmed_at).length>=5){feedback.value='最多保留5份待确认凭证，请先移除不用的文件。';break}
  files.value.push({clientId:crypto.randomUUID(),uploadKey:crypto.randomUUID(),file,name:file.name,bytes:file.size,mime:/\.pdf$/i.test(file.name)?'application/pdf':file.type||'image/png',uploadState:'queued',progress:0,error:'',current:true,thumb:/\.pdf$/i.test(file.name)?'':URL.createObjectURL(file)})
 }
  queueMicrotask(runQueue)
}
async function runQueue(){
 if(uploading.value)return;const n=session,row=props.row;uploading.value=true
 try{let task;while(n===session&&(task=files.value.find(f=>f.uploadState==='queued'))){task.uploadState='uploading';task.error='';try{const r=await api.uploadApprovalProof(row.id,row.version,task.file,{uploadKey:task.uploadKey,onProgress:p=>{if(n===session)task.progress=p}});if(n!==session)return;Object.assign(task,r.proof,{can_select:true,can_remove:true,current:true,uploadState:'uploaded',progress:100});if(!proofIds.value.includes(task.id))proofIds.value.push(task.id)}catch(e){if(n!==session)return;task.uploadState='failed';task.error=e.message}}}finally{uploading.value=false;if(n!==session&&props.modelValue)loadFiles()}
}
function retry(file){if(locked.value)return;file.uploadState='queued';file.progress=0;file.error='';runQueue()}
async function remove(file){if(locked.value)return;const n=session;working.value=true;error.value='';try{let id=file.id;if(!id&&file.uploadState==='failed'&&file.uploadKey){const r=await api.approvalProofs(props.row.id);id=r.items.find(p=>p.upload_key===file.uploadKey)?.id}if(id)await api.removeApprovalProof(props.row.id,id);if(n!==session)return;files.value=files.value.filter(f=>f!==file);proofIds.value=proofIds.value.filter(id=>id!==file.id);if(file.thumb)URL.revokeObjectURL(file.thumb)}catch(e){if(n===session)error.value=e.message}finally{working.value=false}}
async function blob(file){if(file.thumb)return file.thumb;const n=session,b=await api.downloadApprovalProof(props.row.id,file.id);if(n!==session)return '';file.thumb=URL.createObjectURL(b);return file.thumb}
async function view(file){if(file.mime==='application/pdf')return download(file);if(locked.value&&!file.thumb)return;const n=session;working.value=true;error.value='';try{const url=await blob(file);if(n===session)previewUrl.value=url}catch(e){if(n===session)error.value=e.message}finally{working.value=false}}
async function download(file){if(locked.value)return;const n=session;working.value=true;error.value='';try{const url=await blob(file);if(n!==session||!url)return;const a=document.createElement('a');a.href=url;a.download=file.name;a.click()}catch(e){if(n===session)error.value=e.message}finally{working.value=false}}
async function submit(){if(submitHint.value)return;const n=session,row=props.row;submitting.value=true;error.value='';try{await api.approvalAction(row.id,{action:action.value==='reopen'?'reopen':'complete',version:row.version,note:note.value,confirm:confirmed.value,proof_ids:proofIds.value});if(n===session){emit('saved');emit('update:modelValue',false)}}catch(e){if(n===session)error.value=e.message}finally{submitting.value=false}}
onBeforeUnmount(()=>{session++;clear()})
</script>
<style scoped>
.payment-confirmation{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.4fr);gap:24px;align-items:start}.payment-overview{background:var(--el-fill-color-light);border:1px solid var(--el-border-color-lighter);border-radius:10px;padding:20px;min-width:0}.payment-amount>span:not(.el-tag),.payment-reason>span{display:block;font-size:12px;color:var(--el-text-color-secondary)}.payment-amount strong{display:block;font-size:30px;font-weight:650;letter-spacing:-.5px;color:var(--el-text-color-primary);margin:8px 0 12px}.payment-fields{display:grid;gap:14px;margin:22px 0}.payment-fields div{display:grid;grid-template-columns:76px minmax(0,1fr);gap:10px;align-items:baseline}.payment-fields dt{font-size:12px;color:var(--el-text-color-secondary)}.payment-fields dd{margin:0;font-size:13px;line-height:1.6;overflow-wrap:anywhere;color:var(--el-text-color-primary)}.payment-number{font-variant-numeric:tabular-nums}.payment-reason{border-top:1px solid var(--el-border-color-lighter);padding-top:16px}.payment-reason p{font-size:13px;line-height:1.8;margin:8px 0 0;overflow-wrap:anywhere;white-space:pre-wrap}.payment-workarea{min-width:0}.payment-workarea h3{margin:0;font-size:15px;color:var(--el-text-color-primary);font-weight:600}.payment-section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.payment-section-title>span{font-size:12px;color:var(--el-text-color-secondary)}.payment-required{font-size:11px;font-weight:400;color:var(--el-color-danger);margin-left:8px}.payment-dropzone :deep(.el-upload){display:block}.payment-dropzone :deep(.el-upload-dragger){padding:18px 12px;border-radius:8px;background:var(--el-color-primary-light-9)}.payment-upload-icon{font-size:30px;color:var(--el-color-primary);margin-bottom:6px}.payment-upload-title{font-size:13px;color:var(--el-text-color-primary)}.payment-upload-title span{color:var(--el-color-primary);margin-left:4px}.payment-dropzone p{font-size:12px;color:var(--el-text-color-secondary);margin:7px 0 0;line-height:1.6}.payment-empty{font-size:12px;color:var(--el-text-color-secondary);padding:16px 0;line-height:1.7}.payment-file-list{list-style:none;padding:0;margin:12px 0}.payment-file{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--el-border-color-lighter);border-radius:8px;margin-bottom:8px;min-width:0}.payment-file.is-failed{border-color:var(--el-color-danger-light-5);background:var(--el-color-danger-light-9)}.payment-file-thumb{display:flex;flex-direction:column;align-items:center;justify-content:center;width:48px;height:54px;flex-shrink:0;border:0;border-radius:6px;background:var(--el-fill-color);color:var(--el-text-color-secondary);overflow:hidden;cursor:pointer}.payment-file-thumb img{width:100%;height:100%;object-fit:cover}.payment-file-thumb .el-icon{font-size:22px}.payment-file-thumb span{font-size:10px;margin-top:4px}.payment-file-info{min-width:0;flex:1}.payment-file-info strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px;font-weight:500;line-height:1.8;color:var(--el-text-color-primary)}.payment-file-meta{display:flex;flex-wrap:wrap;gap:8px;font-size:11px;color:var(--el-text-color-secondary);margin:3px 0}.payment-file-error{font-size:12px;color:var(--el-color-danger);margin:4px 0 0;overflow-wrap:anywhere}.payment-file-actions{display:flex;align-items:center;gap:10px;flex-shrink:0}.payment-file-actions .el-button+.el-button{margin-left:0}.payment-file-actions :deep(.el-checkbox__label){font-size:12px}.payment-note{margin-top:20px}.payment-note :deep(.el-form-item){margin-bottom:12px}.payment-confirm-check{height:auto;align-items:flex-start;white-space:normal;margin:4px 0}.payment-confirm-check :deep(.el-checkbox__input){margin-top:3px}.payment-confirm-check :deep(.el-checkbox__label){white-space:normal;font-size:12px;line-height:1.8}.payment-review{font-size:12px;line-height:1.7;margin:0 0 16px;padding:10px 12px;border-radius:6px;background:var(--el-color-warning-light-9);color:var(--el-color-warning-dark-2)}.payment-helper,.payment-feedback{font-size:12px;line-height:1.8;color:var(--el-text-color-secondary);margin:12px 0}.payment-history{font-size:12px;margin:12px 0;color:var(--el-text-color-secondary)}.payment-history summary{cursor:pointer;padding:8px 0}.payment-history ul{padding:0;list-style:none}.payment-history li{display:flex;gap:10px;align-items:center;padding:6px 0}.payment-history li>span{flex:1;overflow-wrap:anywhere}.payment-history small{display:block}.payment-read-note{margin-top:20px}.payment-read-note p{line-height:1.8;white-space:pre-wrap;font-size:13px}.payment-footer-hint{flex:1;min-width:160px;text-align:left;font-size:12px;color:var(--el-text-color-secondary);line-height:1.6}.payment-file-thumb:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}
@media(max-width:760px){.payment-confirmation{grid-template-columns:1fr;gap:20px}.payment-overview{padding:16px}.payment-fields{grid-template-columns:1fr 1fr;gap:12px}.payment-fields div{display:block}.payment-fields dd{margin-top:4px}.payment-amount strong{font-size:26px}.payment-file{gap:8px;padding:10px}.payment-file-actions{flex-direction:column;gap:0}.payment-footer-hint{flex-basis:100%;min-width:0}.payment-file-thumb{width:40px;height:48px}}
</style>
